/**
 * SEF-277 — Type-tolerant approver/assignee display resolution.
 *
 * Approver values (`first_approver`, `second_approver`, `assigned_to`) are
 * persisted as a **string** user id (e.g. "42" from getUserDetails().id), while
 * the approver `q-select` options (`dropdown.store.ts` `usersList`) carry the
 * **numeric** `users_cache.id` (42). Quasar `map-options` does a *strict*
 * compare, so "42" !== 42 → no option matches → slotted selects render an empty
 * label and slot-less selects render the raw id/UUID.
 *
 * These helpers resolve a model value to a human-readable name using a
 * String()-normalized ("loose") lookup, and NEVER fall through to a raw id.
 * After a reject the document can be assigned to a group (UUID), so resolution
 * also falls back to the groups list before yielding a safe empty placeholder.
 */

export interface LabeledOption {
  value: any;
  label?: string;
  [key: string]: any;
}

/**
 * Resolve an id-like model value to its display label via a type-tolerant
 * (String-normalized) lookup against the users list first, then the groups
 * list. Returns '' when the value is empty or resolves to neither — the caller
 * must render a safe placeholder, never the raw id.
 */
export function resolveApproverLabel(
  value: any,
  usersList: LabeledOption[] = [],
  groupsList: LabeledOption[] = [],
): string {
  if (value === null || value === undefined || value === '') {
    return '';
  }

  const key = String(value);

  const user = (usersList || []).find(
    (u: LabeledOption) => u != null && String(u.value) === key,
  );
  if (user) {
    return user.label ?? '';
  }

  const group = (groupsList || []).find(
    (g: LabeledOption) => g != null && String(g.value) === key,
  );
  if (group) {
    return group.label ?? '';
  }

  return '';
}

/**
 * Resolve the label for a Quasar `selected-item` slot scope option.
 *
 * When `map-options` matched, `opt` is the option object `{ value, label }` and
 * we can use its label directly. When the strict compare failed, Quasar hands
 * the raw model value (a scalar id) as `opt`, so we resolve it ourselves.
 * Never returns a raw id — an unresolved value yields ''.
 */
export function resolveSelectedItemLabel(
  opt: any,
  usersList: LabeledOption[] = [],
  groupsList: LabeledOption[] = [],
): string {
  if (
    opt != null &&
    typeof opt === 'object' &&
    opt.label !== undefined &&
    opt.label !== null &&
    opt.label !== ''
  ) {
    return opt.label;
  }

  const rawValue = opt != null && typeof opt === 'object' ? opt.value : opt;
  return resolveApproverLabel(rawValue, usersList, groupsList);
}
